"""Self-contained, readable report from actual graph and test outputs."""
import json,html
from sources import HERE,read
def main():
 graph=read(HERE/'private/graph.json');spec=read(HERE/'private/spec.json');v=read(HERE/'private/validation.json')
 data={'graph':graph,'spec':spec,'validation':v,'cases':read(HERE/'private/development.json'),
  'changes':read(HERE/'private/change_log.json'),'reading':read(HERE/'private/source_reading.json'),
  'review':read(HERE/'private/review_resolution.json') if (HERE/'private/review_resolution.json').exists() else []}
 template=r'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>질문 지식 정제 — 무엇을 고쳤고, 무엇이 남았나</title>
<style>
:root{--ink:#162c42;--muted:#53687b;--line:#d6e0e9;--blue:#1764aa;--bg:#f3f6fa}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:17px/1.7 system-ui,'Malgun Gothic',sans-serif}main{max-width:1130px;margin:auto;padding:36px 24px 70px}h1{font-size:30px;line-height:1.4;margin:8px 0 15px}h2{font-size:23px;margin-top:0}h3{font-size:19px}.sub{color:var(--muted)}.box{padding:24px;background:white;border:1px solid var(--line);border-radius:13px;margin:20px 0}.callout{border-left:5px solid var(--blue);padding:12px 20px;background:#edf5ff}.warn{border-left-color:#b27320;background:#fff8e9}.pills{display:flex;gap:12px;flex-wrap:wrap}.pill{padding:10px 17px;background:#e9f1fb;border-radius:8px}.pill b{display:block;font-size:25px}.tabs{position:sticky;top:0;background:var(--bg);padding:12px 0;display:flex;gap:8px;z-index:1}button,select{font:inherit;padding:9px 15px;border:1px solid #b8c9d8;border-radius:7px;background:white;color:var(--ink)}button{cursor:pointer}button[aria-selected=true]{background:var(--blue);color:white;border-color:var(--blue)}.view[hidden]{display:none}table{width:100%;border-collapse:collapse;font-size:16px}th,td{text-align:left;vertical-align:top;padding:12px;border-bottom:1px solid var(--line)}th{background:#edf3f9}td:first-child{font-weight:600}.scroll{overflow:auto}details{margin:16px 0}summary{cursor:pointer;color:var(--blue)}pre{font-size:13px;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7fa;padding:16px}code{overflow-wrap:anywhere}svg{width:100%;min-width:740px;max-height:380px}a{color:var(--blue)}.small{font-size:14px;color:var(--muted)}.step{padding:15px 18px;background:#f5f8fc;margin:10px 0;border-radius:8px}.step strong{color:var(--blue)}.tag{font-size:14px;padding:3px 8px;border-radius:5px;background:#edf3f9}.quote{font-size:15px;border-left:3px solid #b2cbe3;padding-left:15px;white-space:pre-wrap}.next{font-size:18px}footer{font-size:14px;color:var(--muted)}@media(max-width:650px){main{padding:20px 12px}.box{padding:18px}h1{font-size:25px}th,td{padding:8px}}
</style><main>
<div class="sub">연구 기록 · 2026-11-02 · 별도 지식 버전 r3</div><h1>질문에 맞는 규칙을 찾고,<br>어디를 어떻게 고칠지 알려주도록 바꿨습니다.</h1>
<div class="callout"><b>완료한 것:</b> 원문 근거 정리 → 실제 조건으로 조회 → 구체적인 수정 지시 작성.<br><b>아직 하지 않은 것:</b> 모델의 문장 분석과 Qwen의 방언 문장 생성. 자연스러움은 아직 검증하지 않았습니다.</div>
<nav class="tabs"><button data-view="answer" aria-selected="true">1. 바뀐 점</button><button data-view="example">2. 예문으로 보기</button><button data-view="evidence">3. 근거와 검토</button></nav>
<section id="answer" class="view"><div class="box"><h2>이번에 고친 네 가지</h2><div class="scroll"><table><thead><tr><th>문제</th><th>바꾼 내용</th><th>왜 필요한가</th></tr></thead><tbody id="changes"></tbody></table></div></div>
<div class="box"><h2>검사 결과</h2><div id="metrics" class="pills"></div><p>검사는 <b>정해 준 분석값으로 올바른 지식에 도달하는지</b>를 확인합니다. 번역 정확도나 자연스러움 점수가 아닙니다.</p><p id="readyCounts"></p><p class="small">16건은 개발자가 분석을 직접 적은 검사 사례입니다. 기존 24건과 별개로 집계하되, 새 독립 평가 데이터라고 부르지 않습니다.</p></div>
<div class="box"><h2>범위를 넓히기 전, 이 연결을 확인합니다</h2><p>이번 여섯 용법은 <b>첫 질문 묶음</b>입니다. 전체 KG를 여섯 규칙으로 제한하는 것이 아닙니다. 다른 지역형·높임·확인 질문 등은 다음에 정리할 지식으로 남겼습니다.</p><div class="callout warn">같은 <b>-나</b>도 질문이나 명령에 쓰일 수 있습니다. “물음표가 있다”는 이유만으로 고치지 않습니다. 문장이 무엇을 하려는 말인지 분석값으로 받아 구별합니다.</div><p class="next"><b>다음 작업:</b> 같은 지식을 고정한 채 실제 분석 모델의 결과를 수작업 분석과 비교합니다. 그 뒤 동일한 수정 지시를 Qwen에 보내, 분석·조회·활용 조합 중 처음 틀어진 곳을 따로 확인합니다.</p></div></section>
<section id="example" class="view" hidden><div class="box"><h2>한 문장이 지식을 찾아가는 과정</h2><label>예문 선택 <select id="caseSelect"></select></label><div id="worked"></div><div class="scroll" id="network"></div><p class="small">그림은 선택한 사례의 실제 노드와 간선으로 만듭니다. 전체 KG가 아니라 해당 조회 경로만 보여 줍니다.</p><details><summary>실제 ID와 간선, 전달 데이터 확인</summary><pre id="technical"></pre></details></div>
<div class="box"><h2>16개 사례를 한눈에 보기</h2><div class="scroll"><table><thead><tr><th>ID·원문</th><th>조회한 어미</th><th>전달 준비</th></tr></thead><tbody id="caseTable"></tbody></table></div><p class="small">최종 방언 문장 열은 없습니다. 이번 단계에서 Qwen 문장을 생성하지 않았기 때문입니다.</p></div></section>
<section id="evidence" class="view" hidden><div class="box"><h2>문헌을 어디까지 다시 읽었나</h2><div id="reading"></div><p>총괄과 두 검토자가 같은 핵심 범위를 각각 읽었습니다. 페이지를 나누어 한 사람만 읽고 끝낸 방식이 아닙니다. 추가로 읽은 쪽과 화면 확인 범위는 사람마다 다릅니다.</p><p class="small">D02 각주162는 다른 연구를 재인용합니다. D03·D04·D05는 같은 위키 계열입니다. 같은 뿌리의 자료를 여러 독립 증거로 세지 않습니다.</p></div>
<div class="box"><h2>여섯 용법과 실제 근거</h2><div id="rules"></div></div><div class="box"><h2>검토자 의견을 어떻게 처리했나</h2><div id="reviews"></div><p><a href="dispatch/independent/claude/response.md">Claude 독립 검토</a> · <a href="dispatch/independent/codex/response.md">Codex 독립 검토</a> · <a href="dispatch/cross/claude/response.md">Claude 교차 검토</a> · <a href="dispatch/cross/codex/response.md">Codex 교차 검토</a></p></div>
<div class="box"><h2>아직 남은 문제</h2><div id="observations"></div><p><b>현재 만들어진 것은 문헌에 근거한 후보입니다.</b> 현대 경상도 화자가 자연스럽게 쓰는지, 모델이 같은 뜻으로 분석하는지, 완성형을 잘 조합하는지는 별도 확인이 필요합니다.</p></div></section>
<footer>기존 운영 KG·카드·과거 결과는 보존했습니다. 원문 발췌가 있는 이 보고서는 로컬 private 자료입니다.<br>구조 검사 원본: <a href="validation.json">validation.json</a> · 전체 그래프: <a href="graph.json">graph.json</a> · 읽은 범위: <a href="source_reading.json">source_reading.json</a></footer>
<script type="application/json" id="data">@DATA@</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nodes=Object.fromEntries(D.graph.nodes.map(n=>[n.id,n])),edges=Object.fromEntries(D.graph.edges.map(e=>[e.id,e]));
const names={question_kind:'질문 뜻',predicate_class:'서술어 종류',prefinal_type:'선어말',polar:'예/아니오 질문',wh:'구체적인 답 질문',copula:'이다 구성',verb:'동사',adjective:'형용사',none:'없음',eoss:'-었- 계열',present:'현재',past:'과거',positive:'긍정',negative:'부정'};
const ready={ready_for_generation_trial:'전달 정보 준비됨',needs_analysis:'분석 정보 더 필요',out_of_slice:'이번 지원 범위 밖',no_matching_usage:'일치 용법 없음'};
$('changes').innerHTML=D.changes.map(x=>`<tr><td>${esc(x.before)}</td><td>${esc(x.after)}</td><td>${esc(x.why)}</td></tr>`).join('');
$('metrics').innerHTML=[[D.validation.tests_run+'개','구조 검사 / 실패 '+(D.validation.failures+D.validation.errors)],[D.validation.previous_cases.matched+'/'+D.validation.previous_cases.total,'기존 후보 결과 일치'],[D.validation.nodes+' / '+D.validation.edges,'새 그래프 노드 / 관계'],['0회','Qwen 실행']].map(([n,t])=>`<div class="pill"><b>${esc(n)}</b>${esc(t)}</div>`).join('');
$('readyCounts').textContent=Object.entries(D.validation.readiness_counts).map(([k,v])=>(ready[k]||k)+' '+v+'건').join(' · ');
for(const row of D.cases){const o=document.createElement('option');o.value=row.id;o.textContent=row.id+' · '+row.analysis.text;$('caseSelect').appendChild(o)}
$('caseSelect').value='Q05';$('caseSelect').addEventListener('change',worked);
$('caseTable').innerHTML=D.cases.map(r=>{const p=r.packet.clauses[0];return `<tr><td>${esc(r.id)} · ${esc(r.analysis.text)}</td><td>${esc(p.choices.flatMap(x=>x.forms.map(f=>f.ending)).join(', ')||'미확정/없음')}</td><td>${esc(ready[p.readiness]||p.readiness)}</td></tr>`}).join('');
function worked(){const row=D.cases.find(x=>x.id===$('caseSelect').value),c=row.analysis.clauses[0],q=row.retrieval.clauses[0],p=row.packet.clauses[0];
 const count=q.narrowing.map(x=>`${names[x.feature]}=${names[x.value]||x.value}: ${x.before}→${x.after}`).join(' / ');
 $('worked').innerHTML=`<div class="step"><strong>① 입력</strong> ${esc(row.analysis.text)}<br>고칠 대상: <b>${esc(c.target_text)}</b></div><div class="step"><strong>② 수작업 분석</strong> ${['question_kind','predicate_class','prefinal_type'].map(k=>esc(names[k]+': '+(names[c.features[k]]||'미확정'))).join(' · ')}</div><div class="step"><strong>③ 조건으로 좁히기</strong><br>${esc(count)}<br>판정: ${esc(ready[p.readiness]||p.readiness)}</div><div class="step"><strong>④ 전달할 내용</strong><br>${p.choices.map(x=>'어미 '+esc(x.forms.map(f=>f.selected_combining_form||f.ending).join('/'))+' · '+esc(x.meaning)).join('<br>')||'질문 뜻이나 지원 범위를 먼저 확인합니다.'}<br>${p.morphology?'어간: '+esc(p.morphology.stem)+' · 보존할 선어말: '+esc(p.morphology.prefinals.join('+')||'없음'):''}<br>빠진 분석: ${esc(p.needs_analysis.join(', ')||'없음')}<br><b>이번 단계에서는 Qwen에 보내지 않았습니다.</b></div>`;
 const item=q.eligible[0]||q.unresolved[0];
 if(!item){$('network').innerHTML='<p>이번 범위에서 확정된 생성 경로가 없습니다.</p>';$('technical').textContent=JSON.stringify({retrieval:row.retrieval,packet:row.packet},null,2);return;}
 const rid=item.rule_id,rn=nodes[rid],form=item.realization_edges[0],fn=nodes[form.target];
 let boxes='';item.checks.forEach((ch,i)=>{const y=22+i*91;boxes+=`<rect x="10" y="${y}" width="250" height="70" rx="9" fill="#e9f2fc" stroke="#aec8df"/><text x="25" y="${y+27}" font-size="16">조건: ${esc(names[ch.feature])}</text><text x="25" y="${y+52}" font-size="14">${esc(ch.allowed.map(v=>names[v]||v).join(' / '))}</text><path d="M340 149 L262 ${y+35}" fill="none" stroke="#527a9f" marker-end="url(#arrow)"/>`});
 const evid=item.evidence_edges[0],ep=nodes[evid.target].properties;
 $('network').innerHTML=`<svg viewBox="0 0 1190 345" style="min-width:1030px" role="img" aria-label="실제 간선 방향: 용법에서 분기, 분기에서 조건, 용법에서 실현형과 근거"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#527a9f"/></marker></defs>${boxes}<text x="271" y="45" font-size="13">ALL</text><rect x="340" y="115" width="150" height="68" rx="9" fill="#edf2f7" stroke="#aec8df"/><text x="357" y="143" font-size="16">조건 묶음</text><text x="357" y="166" font-size="14">모두 만족</text><path d="M585 149 L492 149" stroke="#527a9f" marker-end="url(#arrow)"/><text x="498" y="132" font-size="12">ANY_BRANCH</text><rect x="585" y="105" width="355" height="88" rx="10" fill="#1764aa"/><text x="598" y="138" fill="white" font-size="15">${esc(rn.properties.title)}</text><text x="598" y="166" fill="white" font-size="14">재사용할 문법 용법</text><path d="M940 149 L1030 149" stroke="#527a9f" marker-end="url(#arrow)"/><text x="947" y="132" font-size="12">REALIZES</text><rect x="1032" y="110" width="140" height="78" rx="10" fill="#e8f5ef" stroke="#aacdba"/><text x="1070" y="157" font-size="28">${esc(fn.properties.form)}</text><path d="M760 193 L760 265" stroke="#527a9f" marker-end="url(#arrow)"/><text x="775" y="233" font-size="12">SUPPORTED_BY</text><rect x="585" y="267" width="355" height="53" rx="9" fill="#f6f0df" stroke="#d2c297"/><text x="600" y="298" font-size="15">근거 중 하나: ${esc(ep.document_id)} PDF ${ep.pdf_page}쪽</text></svg><p class="small">화살표는 저장된 관계 방향입니다. 조회할 때는 조건 쪽에서 관계를 거꾸로 찾아 용법으로 이동할 수 있습니다.</p>`;
 const path=[...item.path_edge_ids,...item.realization_edges.map(e=>e.id),...item.evidence_edges.map(e=>e.id)];
 $('technical').textContent=JSON.stringify({selected_rule:rid,path:path.map(id=>edges[id]),retrieval:row.retrieval,packet:row.packet},null,2);
}
const counts={};for(const p of D.reading.primary_pages)counts[p.doc]=(counts[p.doc]||0)+1;
$('reading').innerHTML='<p>'+Object.entries(counts).map(([d,n])=>esc(d+' '+n+'쪽')).join(' · ')+' = 지정 본문 25쪽</p><p>총괄은 추가로 D02 136–138쪽 본문과 연결 각주를 확인했습니다. PDF 화면을 직접 대조한 쪽: D02 145·146, D04 8·10·11, D05 24, D03 3.</p>';
$('rules').innerHTML=D.spec.rules.map(r=>`<details><summary>${esc(r.title)} · ${esc(r.forms.map(f=>f.form).join('/'))}</summary><p>${esc(r.meaning)}</p><p>이전 항목 연결: ${esc(r.legacy_atom_ids.join(', '))}</p>${r.primary_evidence_ids.map(id=>{const e=D.spec.evidence[id];return `<p><b>${esc(e.document_id)} PDF ${e.pdf_page}쪽</b> · ${esc(e.evidence_kind)}</p><div class="quote">${esc(e.quote)}</div><p>${esc(e.builder_paraphrase)}</p>`}).join('')}<p class="small">${esc(r.realization_basis)}</p></details>`).join('');
$('reviews').innerHTML=D.review.length?'<table><thead><tr><th>검토 의견</th><th>총괄 처리</th></tr></thead><tbody>'+D.review.map(r=>`<tr><td>${esc(r.issue)}</td><td>${esc(r.decision)}</td></tr>`).join('')+'</tbody></table>':'<p>교차 검토 수집 중입니다.</p>';
$('observations').innerHTML=D.spec.observations.map(o=>`<p><b>${esc(o.title)}</b> — ${esc(o.meaning)}</p>`).join('');
for(const b of document.querySelectorAll('nav button'))b.addEventListener('click',()=>{for(const t of document.querySelectorAll('nav button')){const active=t===b;t.setAttribute('aria-selected',String(active));$(t.dataset.view).hidden=!active}});
worked();
</script></main></html>'''
 output=template.replace('@DATA@',json.dumps(data,ensure_ascii=False).replace('<','\\u003c'))
 (HERE/'private/report.html').write_text(output,encoding='utf8')
 print('report generated',len(output))
if __name__=='__main__':main()
